import{_ as i,H as l,o as E,c as B,aN as e,q as r,s as A,a as n,l as o,aT as s}from"./chunks/framework.D31DlcCL.js";const D=JSON.parse('{"title":"AI大模型修仙传（六）：从GPT到LLM——为什么参数大了就能“涌现”智能？","description":"为什么把参数堆到千亿级别，原本只会“文字接龙”的AI突然就有了逻辑推理能力？本文带你硬核扒开大模型“涌现”智能的底裤，搞懂预训练、微调与Scaling Laws的修仙秘籍。","frontmatter":{"title":"AI大模型修仙传（六）：从GPT到LLM——为什么参数大了就能“涌现”智能？","date":"2026-04-01T00:00:00.000Z","categories":["AI"],"tags":["大语言模型","GPT","涌现能力","Scaling Laws","AI修仙传"],"description":"为什么把参数堆到千亿级别，原本只会“文字接龙”的AI突然就有了逻辑推理能力？本文带你硬核扒开大模型“涌现”智能的底裤，搞懂预训练、微调与Scaling Laws的修仙秘籍。"},"headers":[],"relativePath":"posts/ai-series-6-llm-evolution.md","filePath":"posts/ai-series-6-llm-evolution.md","lastUpdated":null}'),p={name:"posts/ai-series-6-llm-evolution.md"};function g(d,a,_,T,h,m){const t=l("Mermaid");return E(),B("div",null,[a[3]||(a[3]=e('<h1 id="ai大模型修仙传-六-从gpt到llm——为什么参数大了就能-涌现-智能" tabindex="-1">AI大模型修仙传（六）：从GPT到LLM——为什么参数大了就能“涌现”智能？ <a class="header-anchor" href="#ai大模型修仙传-六-从gpt到llm——为什么参数大了就能-涌现-智能" aria-label="Permalink to &quot;AI大模型修仙传（六）：从GPT到LLM——为什么参数大了就能“涌现”智能？&quot;">​</a></h1><blockquote><p><strong>💡 博主导读</strong>：大模型为什么会产生“涌现”？这是过去两年AI界最迷人也最玄幻的话题。作为技术探路者，我整理了这三张核心图解，帮你一秒看透大模型进化的底层密码。</p></blockquote><h1 id="ai大模型修仙传-六-从gpt到llm——为什么参数大了就能-涌现-智能-1" tabindex="-1">AI大模型修仙传（六）：从GPT到LLM——为什么参数大了就能“涌现”智能？ <a class="header-anchor" href="#ai大模型修仙传-六-从gpt到llm——为什么参数大了就能-涌现-智能-1" aria-label="Permalink to &quot;AI大模型修仙传（六）：从GPT到LLM——为什么参数大了就能“涌现”智能？&quot;">​</a></h1><p>各位道友，欢迎回到《AI大模型修仙传》。</p><p>几年前，当我们调戏AI时，它还是个连话都说不囫囵的“人工智障”。你问它“番茄炒蛋怎么做”，它可能会回答“番茄炒蛋是一种美味的番茄炒蛋”。</p><p>但突然有一天，这玩意儿不仅能给你写出带有莎士比亚风格的番茄炒蛋菜谱，顺便还能帮你改一段祖传的C++代码，甚至能敏锐地察觉到你今天心情不好。</p><p>从早期的GPT到如今百花齐放的LLM（大型语言模型），这中间到底发生了什么？为什么科学家们只是疯狂地给它“喂数据”和“加参数”，它就突然开窍了？</p><p>今天，我们就来扒一扒大模型从“炼气期”突破到“元婴期”的核心修仙秘籍：<strong>预训练、微调、Scaling Laws，以及最神秘的——“涌现”</strong>。</p><hr><h2 id="第一步-预训练-pre-training-——-填鸭式阅读与-文字接龙-大宗师" tabindex="-1">第一步：预训练（Pre-training）—— 填鸭式阅读与“文字接龙”大宗师 <a class="header-anchor" href="#第一步-预训练-pre-training-——-填鸭式阅读与-文字接龙-大宗师" aria-label="Permalink to &quot;第一步：预训练（Pre-training）—— 填鸭式阅读与“文字接龙”大宗师&quot;">​</a></h2>',10)),(E(),r(s,null,{default:A(()=>[o(t,{id:"mermaid-30",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20Data%5B%E6%B5%B7%E9%87%8F%E4%BA%92%E8%81%94%E7%BD%91%E6%96%87%E6%9C%AC%5D%20--%3E%20Model%5B%E6%9C%AA%E8%AE%AD%E7%BB%83%E7%9A%84%E5%9F%BA%E7%A1%80%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20Model%20--%3E%20Predict%5B%E9%A2%84%E6%B5%8B%E4%B8%8B%E4%B8%80%E4%B8%AA%E8%AF%8D%3A%20%E5%BA%8A%E5%89%8D%E6%98%8E%E6%9C%88_%5D%0A%20%20%20%20Predict%20--%3E%7C%E9%94%99%E8%AF%AF%3A%20%E9%A5%BC%7C%20Loss%5B%E8%AE%A1%E7%AE%97%E6%8D%9F%E5%A4%B1%5D%0A%20%20%20%20Loss%20--%3E%7C%E5%8F%8D%E5%90%91%E4%BC%A0%E6%92%AD%7C%20Update%5B%E8%B0%83%E6%95%B4%E7%99%BE%E4%BA%BF%E5%8F%82%E6%95%B0%5D%0A%20%20%20%20Update%20--%3E%20Model%0A%20%20%20%20style%20Model%20fill%3A%23bbf%2Cstroke%3A%23333%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<p>如果把培养大模型比作修仙，那么<strong>预训练</strong>（Pre-training）就是最漫长、最枯燥的“炼气期”。</p><p>在这个阶段，科学家们（各大宗门长老）不教模型任何具体的技能，比如怎么做算术、怎么翻译英语。他们只做一件事：把人类几千年来在互联网上留下的所有文本（维基百科、论文、新闻、论坛贴吧甚至网友对骂），打包成一座藏经阁，把AI一脚踹进去，让它闭关死读。</p><p>AI在藏经阁里怎么修炼呢？大道至简，它只练一招：<strong>文字接龙（Next Token Prediction）</strong>。</p><p>当它看到“床前明月”时，它要去猜下一个字是什么。 一开始它可能猜是“饼”，系统会无情地给它一巴掌（计算Loss损失函数），告诉它正确答案是“光”。 被打了几万亿次之后，模型内部的神经网络（灵脉）开始疯狂调整权重（参数）。</p><p>你以为它只是背下了全网的文章？格局小了。 为了能精准地预测出下一个词，AI<strong>被迫</strong>去理解这个世界的运转规律。 比如看到“因为今天下雨，所以我出门带了___”，它要填“伞”，就必须在它那几百亿的参数中，建立起“下雨”和“带伞”之间的因果逻辑映射。</p><p><strong>预训练结束时，AI已经拥有了极其磅礴的内力，通晓古今，但它是个“野生大能”</strong>——你问它一个问题，它可能不回答你，而是顺着你的问题继续往下写（因为它的本能只是文字接龙）。</p><hr><h2 id="第二步-微调-fine-tuning-——-从-野生大能-到-金牌客服" tabindex="-1">第二步：微调（Fine-tuning）—— 从“野生大能”到“金牌客服” <a class="header-anchor" href="#第二步-微调-fine-tuning-——-从-野生大能-到-金牌客服" aria-label="Permalink to &quot;第二步：微调（Fine-tuning）—— 从“野生大能”到“金牌客服”&quot;">​</a></h2>',8)),(E(),r(s,null,{default:A(()=>[o(t,{id:"mermaid-53",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Base%5B%E9%A2%84%E8%AE%AD%E7%BB%83%E6%A8%A1%E5%9E%8B%20Base%20Model%5D%20--%3E%20SFT%5B%E7%9B%91%E7%9D%A3%E5%BE%AE%E8%B0%83%20SFT%3A%20%E5%AD%A6%E4%B9%A0%E4%BA%BA%E7%B1%BB%E9%97%AE%E7%AD%94%E6%A0%BC%E5%BC%8F%5D%0A%20%20%20%20SFT%20--%3E%20Reward%5B%E8%AE%AD%E7%BB%83%E5%A5%96%E5%8A%B1%E6%A8%A1%E5%9E%8B%20Reward%20Model%5D%0A%20%20%20%20Reward%20--%3E%20RLHF%5BRLHF%3A%20%E4%BA%BA%E7%B1%BB%E5%8F%8D%E9%A6%88%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%5D%0A%20%20%20%20RLHF%20--%3E%20Chat%5B%E6%9C%80%E7%BB%88%E7%9A%84%E5%AF%B9%E8%AF%9D%E6%A8%A1%E5%9E%8B%20ChatGPT%5D%0A%20%20%20%20style%20RLHF%20fill%3A%23f9f%2Cstroke%3A%23333%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=e('<p>预训练出来的基础模型（Base Model）虽然内力深厚，但桀骜不驯。这时候就需要进入“筑基期”，也就是<strong>微调（Fine-tuning）</strong>。</p><p>微调的核心目的，是给AI立规矩，教它怎么“像个人类助手一样聊天”。这里面有两大绝招：</p><ol><li><p><strong>SFT（监督微调，Supervised Fine-Tuning）</strong>： 宗门长老亲自下场，写了几万道经典的“问答题”示范给AI看。 人类：“请帮我写一封辞职信。” 示范答案：“尊敬的老板：世界那么大，我想去看看……” AI一看，哦！原来人类想要的是一问一答的模式，而不是让我顺着“辞职信”接着往下水字数！</p></li><li><p><strong>RLHF（基于人类反馈的强化学习）</strong>： 这招更绝，相当于给AI找了个“陪练导师”。AI对同一个问题生成三个回答，人类导师在旁边打分：“回答A太生硬，0分；回答B有脏话，扣10分；回答C礼貌又专业，满分！” 通过这种“胡萝卜加大棒”的训练，AI不仅学会了好好说话，还学会了迎合人类的价值观（比如不生成有害内容，保持中立客观）。</p></li></ol><p>经过微调，一个狂野的“文字接龙机器”，就彻底脱胎换骨，变成了你能看到的、彬彬有礼且无所不知的ChatGPT或文心一言。</p><hr><h2 id="暴力美学-scaling-laws-缩放定律-——-别整花里胡哨的-加卡" tabindex="-1">暴力美学：Scaling Laws（缩放定律）—— 别整花里胡哨的，加卡！ <a class="header-anchor" href="#暴力美学-scaling-laws-缩放定律-——-别整花里胡哨的-加卡" aria-label="Permalink to &quot;暴力美学：Scaling Laws（缩放定律）—— 别整花里胡哨的，加卡！&quot;">​</a></h2><p>讲到这里，有道友要问了：既然原理这么简单（不就是文字接龙+人工教导吗），为什么前几年大家没搞出来，非要等到现在？</p><p>这就不得不提AI修仙界的第一铁律，由OpenAI率先参透的<strong>Scaling Laws（缩放定律）</strong>。</p><p>过去，AI界的高手们喜欢钻研“精妙的招式”（复杂的网络架构），试图用少量的算力四两拨千斤。 但Scaling Laws残忍地打破了这个幻想。它指出：<strong>在Transformer架构下，模型的性能与计算量、数据量、参数量之间，存在着极其严密且可预测的数学关系。</strong></p><p>翻译成大白话就是：<strong>别整那些花里胡哨的，加卡（GPU）！加数据！加大参数！大力出奇迹！</strong></p><p>只要你投入的算力增加十倍，模型的智商就会稳定地提升一个台阶。这种不讲武德的“重剑无锋”，直接开启了如今大厂之间残酷的“算力霸权”军备竞赛。谁有钱买更多的H100，谁就能炼出更强的丹。</p><hr><h2 id="见证奇迹-参数爆炸与智能的-涌现-emergence-——-量变引发的基因突变" tabindex="-1">见证奇迹：参数爆炸与智能的“涌现”（Emergence）—— 量变引发的基因突变 <a class="header-anchor" href="#见证奇迹-参数爆炸与智能的-涌现-emergence-——-量变引发的基因突变" aria-label="Permalink to &quot;见证奇迹：参数爆炸与智能的“涌现”（Emergence）—— 量变引发的基因突变&quot;">​</a></h2>',13)),(E(),r(s,null,{default:A(()=>[o(t,{id:"mermaid-98",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20P1%5B10%E4%BA%BF%E5%8F%82%E6%95%B0%5D%20--%3E%7C%E5%8F%AA%E8%83%BD%E5%81%9A%E7%AE%80%E5%8D%95%E5%A1%AB%E8%AF%8D%7C%20A1(%E6%97%A0%E6%8E%A8%E7%90%86%E8%83%BD%E5%8A%9B)%0A%20%20%20%20P2%5B100%E4%BA%BF%E5%8F%82%E6%95%B0%5D%20--%3E%7C%E8%AF%AD%E6%B3%95%E5%8F%98%E5%A5%BD%7C%20A2(%E5%88%9D%E7%BA%A7%E9%80%BB%E8%BE%91)%0A%20%20%20%20P3%5B1000%E4%BA%BF%E5%8F%82%E6%95%B0%5D%20--%3E%7C%E7%AA%81%E7%A0%B4%E4%B8%B4%E7%95%8C%E7%82%B9%7C%20A3(%E9%A1%BF%E6%82%9F%3A%20%E6%B6%8C%E7%8E%B0%E5%87%BA%E5%86%99%E4%BB%A3%E7%A0%81%2F%E5%A4%8D%E6%9D%82%E6%8E%A8%E7%90%86%E8%83%BD%E5%8A%9B)%0A%20%20%20%20style%20P3%20fill%3A%23ff9%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A%20%20%20%20style%20A3%20fill%3A%23ff9%2Cstroke%3A%23333%2Cstroke-width%3A2px%0A"})]),fallback:A(()=>[...a[2]||(a[2]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=e('<p>如果只是性能线性提升，那LLM还不足以让人惊艳。真正让整个科技界倒吸一口凉气的，是当参数规模突破某个临界点（通常认为是百亿/千亿级别）时，发生的**“涌现”（Emergence）现象**。</p><p>什么是“涌现”？ 一滴水没有漩涡，但一条河有； 一个脑细胞没有意识，但几百亿个脑细胞连在一起，就有了人类的灵魂。</p><p>在AI身上，涌现意味着**“量变引发了质变”**。 当模型只有10亿参数时，它连两位数加减法都算不对，连基本的常识都会搞错。 但当模型参数被暴力堆到1000亿以上时，奇迹发生了： 科学家们从未专门教过它写代码，它突然就会写Python了； 从未专门教过它做逻辑推理，它突然就能解开复杂的数学应用题了； 甚至，它学会了“撒谎”、学会了“懂幽默”、学会了“一步步思考（Chain of Thought）”。</p><p><strong>为什么会这样？</strong> 目前学术界的主流猜测是：当数据和参数大到一定程度，模型为了尽可能降低“预测下一个词”的误差，单纯的“死记硬背”已经不够用了。<strong>它被极其庞大的数据逼迫着，在自己那几千亿个神经元中，硬生生地压缩并抽象出了一个“世界模型”。</strong></p><p>它懂逻辑，是因为只有懂逻辑，才能在千变万化的语境中，永远猜对下一个字。</p><p>这，就是大语言模型最性感的浪漫。</p><hr><h2 id="结语-这只是修仙的起点" tabindex="-1">结语：这只是修仙的起点 <a class="header-anchor" href="#结语-这只是修仙的起点" aria-label="Permalink to &quot;结语：这只是修仙的起点&quot;">​</a></h2><p>从GPT的诞生到如今LLM的百团大战，我们见证了人类如何用最暴力的算力，和最简单的“文字接龙”规则，硬生生在硅基芯片上“涌现”出了一抹智慧的火花。</p><p>但这仅仅是“大模型修仙传”的开局。当一个拥有千亿参数的大脑已经就位，下一步是什么？ 是给它装上手和脚（工具调用），让它去现实世界中帮你订机票、点外卖、甚至代替你上班。</p><p>这就是我们下一期要聊的终极话题：<strong>从LLM到Agent（智能体）——AI是如何开始打工的？</strong></p><p>如果你觉得这篇文章让你对大模型有了顿悟，别忘了<strong>点赞、在看、转发</strong>素质三连！ 各位道友，我们评论区见！</p><blockquote><p><strong>今日互动</strong>：你第一次感受到大模型“真的有脑子”而不是在“死记硬背”，是因为它的哪一句回答？欢迎在评论区分享你的“赛博惊悚时刻”！</p></blockquote>',13))])}const u=i(p,[["render",g]]);export{D as __pageData,u as default};
